// Config ya ha mezclado sus campos hacia aquí (includeOtherFields), así que $json
// lleva cuerpo, cabeceras y configuración a la vez.
const cfg = $json;
const headers = cfg.headers || {};

// --- El cuerpo CRUDO ---
// Retell firma los BYTES que envía: re-serializar el JSON ya parseado no cuadra
// nunca (un espacio de diferencia y el HMAC cambia entero). O tenemos el crudo o
// la firma no se puede comprobar.
//
// `rawBody: true` lo entrega de formas distintas según la versión de n8n, y la
// primera versión de este nodo solo contemplaba una -- trataba `body.data` como
// base64 cuando puede ser un ARRAY DE BYTES, y eso decodificado da basura y un
// HMAC que no coincide jamás. Se aceptan todas las formas y se anota CUÁL
// apareció, para que un fallo futuro se lea en vez de deducirse.
let raw = null, cuerpo = null, forma_cuerpo = 'ausente', origen_cuerpo = 'config';

let b = cfg.body;
// Se lee del WEBHOOK y no de $json: $json lo dejó un nodo Set, y un Set puede
// descartar la parte binaria -- que es justo donde rawBody deja los bytes.
try {
  const hook = $('Webhook · POST /retell-call').first();
  if (hook) {
    origen_cuerpo = 'webhook';
    if (hook.json && hook.json.body !== undefined) b = hook.json.body;
    const bin = hook.binary || {};
    const dato = bin.data || bin.body || Object.values(bin)[0];
    if (dato && dato.data) {
      try { raw = Buffer.from(dato.data, 'base64').toString('utf8');
            forma_cuerpo = 'binario_webhook'; } catch (e) { /* seguimos con b */ }
    }
  }
} catch (e) { /* sin webhook en esta ejecución */ }

if (raw) {
  // resuelto desde el binario
} else if (typeof b === 'string') {
  forma_cuerpo = 'string'; raw = b;
} else if (b && typeof b === 'object' && b.type === 'Buffer' && Array.isArray(b.data)) {
  // OJO: bytes, no base64. Aquí estaba el fallo.
  forma_cuerpo = 'buffer_json';
  try { raw = Buffer.from(b.data).toString('utf8'); } catch (e) { raw = null; }
} else if (typeof Buffer !== 'undefined' && Buffer.isBuffer && Buffer.isBuffer(b)) {
  forma_cuerpo = 'buffer';
  try { raw = b.toString('utf8'); } catch (e) { raw = null; }
} else if (b && typeof b === 'object') {
  forma_cuerpo = 'objeto_parseado'; cuerpo = b;  // el crudo se perdió: sin firma posible
}

if (!raw && !cuerpo) {
  try {
    const bin = $input.first().binary || {};
    const dato = bin.data || bin.body || Object.values(bin)[0];
    if (dato && dato.data) {
      forma_cuerpo = 'binario';
      raw = Buffer.from(dato.data, 'base64').toString('utf8');
    }
  } catch (e) { /* no hay binario */ }
}
if (raw && !cuerpo) { try { cuerpo = JSON.parse(raw); } catch (e) { cuerpo = null; } }
if (!cuerpo) cuerpo = {};

// --- La firma ---
// El formato de la cabecera lo decide Retell y no está confirmado. En vez de dar
// por bueno un formato, se busca el digest: 64 caracteres hex. Así da igual que
// venga a pelo, como `v1=...` o con marca de tiempo delante.
const cruda = String(headers['x-retell-signature'] || headers['X-Retell-Signature'] || '');
const hex = cruda.match(/[0-9a-fA-F]{64}/);
const sig = hex ? hex[0] : cruda.trim();

// La cabecera real de Retell es `v=<marca de tiempo>,d=<digest>`, y lo firmado es
// el CUERPO SEGUIDO DE LA MARCA -- `raw + ts`, en ese orden. Costó saberlo: se
// probaron tres formas con la marca delante y ninguna cuadraba, porque va detrás.
// Se dejan las otras como tolerancia (cualquiera exige conocer el secreto, así
// que aceptar varias no debilita nada) y la ejecución anota cuál valió.
const mt = cruda.match(/v=(\d+)/);
const ts = mt ? mt[1] : '';
const cuerpoCrudo = raw || '';
const _c1 = ts ? `${cuerpoCrudo}${ts}` : '';   // cuerpo+ts  <- el documentado
const _c2 = cuerpoCrudo;                        // cuerpo solo
const _c3 = ts ? `${ts}${cuerpoCrudo}` : '';    // ts+cuerpo
const _c4 = ts ? `${ts}.${cuerpoCrudo}` : '';   // ts.cuerpo

const evento = String(cuerpo.event || cuerpo.event_type || '').trim();
const llamada = (cuerpo.call && typeof cuerpo.call === 'object') ? cuerpo.call : cuerpo;

return [{ json: {
  evento,
  es_analisis: evento === 'call_analyzed',
  llamada,
  directus_base_url: cfg.directus_base_url,
  canal: cfg.canal,
  tenant_timezone: cfg.tenant_timezone,
  forma_cuerpo, origen_cuerpo,
  _raw: raw || '',
  _ts: ts,
  _c1, _c2, _c3, _c4,
  _sig: sig,
  _sig_cruda: cruda,
  _secret: String(cfg.retell_api_key || ''),
  _require_signature: String(cfg.require_signature).toLowerCase() === 'true',
} }];

// El veredicto se escribe SIEMPRE. La lección de WhatsApp: una comprobación que
// no se puede observar no está funcionando, se está acumulando.
const d = $json;
const recibida = String(d._sig || '');

// Comparación en tiempo constante: una normal filtra el prefijo correcto por lo
// que tarda en fallar.
const igual = (a, b) => {
  if (!a || !b) return false;
  let dif = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    dif |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  }
  return dif === 0;
};

// Retell firma el cuerpo JUNTO a la marca de tiempo de la cabecera
// (`v=<ts>,d=<digest>`). Se prueban las formas plausibles de concatenarlo: que
// cualquiera cuadre ya demuestra conocer el secreto, así que aceptar varias no
// debilita nada, y en cambio sobrevive a que Retell cambie el detalle.
const candidatas = [
  ['cuerpo+ts', d._h1], ['cuerpo', d._h2],
  ['ts+cuerpo', d._h3], ['ts.cuerpo', d._h4],
];
const acierto = candidatas.find(([, h]) => igual(String(h || ''), recibida));

let firma = 'no_verificada';
let firma_motivo = null;
let firma_variante = null;

if (!d._secret || d._secret.startsWith('REPLACE_')) {
  firma_motivo = 'no hay RETELL_API_KEY en el tenant';
} else if (!recibida) {
  firma = 'ausente'; firma_motivo = 'la petición no trae x-retell-signature';
} else if (!d._raw) {
  firma_motivo = `no se pudo recuperar el cuerpo crudo (forma: ${d.forma_cuerpo})`;
} else if (acierto) {
  // Retell pide además rechazar marcas viejas: sin esto, una petición válida
  // capturada una vez se puede reenviar siempre, y la firma seguiría cuadrando.
  const edad = Math.abs(Date.now() - Number(d._ts || 0));
  if (!d._ts || edad > 5 * 60 * 1000) {
    firma = 'caducada';
    firma_motivo = `la marca de tiempo está a ${Math.round(edad / 1000)}s (máximo 300s)`;
  } else {
    firma = 'valida'; firma_variante = acierto[0];
  }
} else {
  firma = 'invalida';
  firma_motivo = 'ninguna de las candidatas coincide con el digest recibido';
}

// Lo justo para diagnosticar sin publicar el secreto ni el contenido: prefijos de
// digest no reconstruyen una clave, y en cambio distinguen "el cuerpo llegó mal"
// de "Retell firma otra cosa".
const detalle = {
  forma_cuerpo: d.forma_cuerpo, origen_cuerpo: d.origen_cuerpo,
  largo_crudo: (d._raw || '').length, marca_tiempo: d._ts || null,
  cabecera_cruda: String(d._sig_cruda || '').slice(0, 30),
  recibida_12: recibida.slice(0, 12),
  calculados_12: candidatas.map(([k, h]) => `${k}:${String(h || '').slice(0, 12)}`),
};

const descartar = d._require_signature && firma !== 'valida';
const salida = { ...d, firma, firma_motivo, firma_variante, firma_detalle: detalle, descartar };
for (const k of ['_secret','_raw','_sig','_sig_cruda','_c1','_c2','_c3','_c4','_h1','_h2','_h3','_h4']) delete salida[k];
return [{ json: salida }];

// Un evento que no es el análisis, o uno con firma inválida cuando se exige.
// Se contesta 200 a propósito: un error haría que Retell lo reintentara en
// bucle, y no hay nada que reintentar.
const d = $json;
return [{ json: { ok: true, guardada: false,
  motivo: d.descartar ? `firma ${d.firma}` : `evento ${d.evento || 'desconocido'}`,
  firma: d.firma, firma_motivo: d.firma_motivo || null,
  firma_detalle: d.firma_detalle || null } }];

// De la forma de Retell a la nuestra. Todo con alternativas: este contrato lo
// define otra empresa y cambiará sin avisarnos, así que un campo que se mueva
// tiene que dejar la nota coja, nunca tumbar el webhook.
const d = $json;
const c = d.llamada || {};
const analisis = (c.call_analysis && typeof c.call_analysis === 'object') ? c.call_analysis : {};
const extra = (analisis.custom_analysis_data && typeof analisis.custom_analysis_data === 'object')
  ? analisis.custom_analysis_data : {};

const limpio = (v) => (v === undefined || v === null) ? null : (String(v).trim() || null);
const corto = (v, max) => { const s = limpio(v); return s ? s.slice(0, max) : null; };

const saliente = String(c.direction || 'inbound').toLowerCase() === 'outbound';

// QUIÉN es el cliente, que no siempre es quien llama: en una llamada SALIENTE el
// cliente es a quien llamamos (`to_number`), no el número desde el que sale.
// Guardar `from_number` ahí habría metido nuestro propio número en su ficha.
const dinamicas = (c.retell_llm_dynamic_variables && typeof c.retell_llm_dynamic_variables === 'object')
  ? c.retell_llm_dynamic_variables : {};
const metadatos = (c.metadata && typeof c.metadata === 'object') ? c.metadata : {};

// Y de DÓNDE se saca, en el mismo orden que el despachador de tools -- que es el
// motivo de que la tarea sí encontrara el contacto y la primera versión de esta
// nota no: en una webcall NO hay número de llamada y el teléfono llega por la
// variable dinámica que fija quien crea la llamada.
let origen_telefono = 'ninguno';
let crudo = limpio(saliente ? c.to_number : c.from_number);
if (crudo) origen_telefono = saliente ? 'to_number' : 'from_number';
if (!crudo && limpio(dinamicas.telefono)) { crudo = limpio(dinamicas.telefono); origen_telefono = 'variable_dinamica'; }
if (!crudo && limpio(metadatos.telefono)) { crudo = limpio(metadatos.telefono); origen_telefono = 'metadata'; }


// Un número español se dice y se teclea sin el 34 la mitad de las veces. En una
// llamada de teléfono `from_number` viene en E.164, pero una variable dinámica,
// un formulario o un webchat no: si eso entra tal cual, la clave del hilo cambia
// (`voz:683187144` en vez de `voz:34683187144`) y el contacto guardado como
// +34... deja de encontrarse. Pasó en demo y no dio ningún error: simplemente
// nadie quedó enlazado.
//
// Regla explícita y deliberadamente estrecha: 9 dígitos que empiezan por 6, 7, 8
// o 9 son un número español. Todo lo demás se deja como viene.
const aE164 = (digitos) => {
  if (/^[6789]\d{8}$/.test(digitos)) return `34${digitos}`;
  return digitos;
};

// E.164 sin '+', igual que WhatsApp, para que quien llama y quien escribe sean
// EL MISMO contacto.
const telefono = aE164((crudo || '').replace(/[^\d]/g, '')) || null;

const ms = Number(c.start_timestamp) || 0;
const fin = Number(c.end_timestamp) || 0;
const start_at = ms ? new Date(ms).toISOString() : new Date().toISOString();
let duracion = Number(c.duration_ms);
if (!Number.isFinite(duracion) || duracion <= 0) duracion = (fin && ms) ? (fin - ms) : 0;

const esSi = (v) => v === true || ['true', 'si', 'sí', 'yes', '1'].includes(String(v).trim().toLowerCase());

return [{ json: {
  directus_base_url: d.directus_base_url,
  call_id: limpio(c.call_id) || limpio(c.callId),
  telefono,
  origen_telefono,
  session_key: telefono ? `${d.canal || 'voz'}:${telefono}` : null,
  start_at,
  duracion_segundos: Math.max(0, Math.round(duracion / 1000)),
  direccion: saliente ? 'saliente' : 'entrante',
  motivo: corto(extra.motivo || extra.reason, 255),
  resultado: corto(extra.resultado || extra.outcome, 255),
  // El resumen es lo ÚNICO que sobrevive: en la plataforma de voz el audio y la
  // transcripción se borran con su retención corta.
  resumen: limpio(analisis.call_summary || extra.resumen),
  requiere_seguimiento: esSi(extra.requiere_seguimiento),
  firma: d.firma,
}}];

// El webhook se reintenta, así que esto es lo NORMAL, no un error. `call_id` es
// UNIQUE en Directus por si dos reintentos llegan a la vez y los dos pasan por
// aquí antes de que ninguno escriba: la restricción es la que de verdad manda.
const n = $('Code · Normalizar').first().json;
return [{ json: { ok: true, guardada: false, motivo: 'ya existía', call_id: n.call_id } }];

// El contacto lo resuelve el MISMO sub-workflow que usan las tools (17, con
// sin_contexto: aquí no hacen falta sus citas), para que la nota y la
// conversación no puedan discrepar sobre quién llamó.
// Se pide por nombre y no por $json: entre medias ahora van la sesión y los
// turnos, y $json es lo que dejó el último de ellos.
const n = $('Code · Normalizar').first().json;
const r = $('Execute · 17 Resolve Contact').first().json || {};
const contact_id = r.contact_id || (r.context && r.context.contact && r.context.contact.id) || null;

return [{ json: {
  directus_base_url: n.directus_base_url,
  fila: {
    call_id: n.call_id,
    contact_id,
    telefono: n.telefono,
    session_key: n.session_key,
    start_at: n.start_at,
    duracion_segundos: n.duracion_segundos,
    direccion: n.direccion,
    motivo: n.motivo,
    resultado: n.resultado,
    resumen: n.resumen,
    requiere_seguimiento: n.requiere_seguimiento,
  },
}}];

// La respuesta dice la VERDAD sobre lo que ha pasado, y eso no es cosmético:
// Retell reintenta ante un error, y con la retención corta ese reintento es la
// única red que queda si Directus estaba caído. Mentir con un 200 alegre
// convertiría un fallo recuperable en un resumen perdido para siempre.
const n = $('Code · Normalizar').first().json;
const f = $('Code · Construir nota').first().json;
const resp = $json || {};
const code = Number(resp.statusCode || 0);
const ok = code >= 200 && code < 300;
const creada = ok ? ((resp.body && resp.body.data && resp.body.data.id) || null) : null;

if (!ok) {
  throw new Error(`No se pudo guardar la nota de la llamada ${n.call_id}: `
    + `Directus devolvió ${code}. Retell reintentará.`);
}
// `contacto` sale en la respuesta a propósito: una nota sin contacto no es un
// error, pero es lo primero que hay que poder mirar cuando la bandeja aparece
// vacía -- y dice además POR DÓNDE se supo el teléfono.
return [{ json: { ok: true, guardada: true, call_id: n.call_id, id: creada,
  contacto: (f.fila && f.fila.contact_id) || null,
  telefono: n.telefono, origen_telefono: n.origen_telefono } }];

// La salida de `17` es $json aquí, pero lo que hace falta viene de otro sitio:
// se pide por nombre, que es la regla de esta casa desde que insertar un nodo
// rompió cuatro cadenas en un día.
const n = $('Code · Normalizar').first().json;
const r = $json || {};
return [{ json: {
  directus_base_url: n.directus_base_url,
  session_key: n.session_key,
  canal: 'voz',
  contact_id: r.contact_id || null,
}}];

// Una llamada es un hilo más de la bandeja, con la MISMA clave que usan las tools
// (`voz:<telefono>`): así la segunda llamada del mismo cliente cae en su hilo en
// vez de abrir uno nuevo, y una llamada y un WhatsApp son conversaciones
// distintas del MISMO contacto.
const b = $('Code · Sesión: buscar').first().json;
const resp = $json || {};
const filas = (resp.body && resp.body.data) || [];
const sesion = filas[0] || null;
const session_id = (sesion && sesion.id) || null;

// Sin teléfono no hay clave de hilo, y un mensaje colgando de nada es peor que no
// registrarlo: es la misma regla que aplica Entry.
const posible = Boolean(b.session_key);

// Si el hilo ya existía SIN contacto y ahora sabemos quién es, se enlaza. Sin
// esto, una sesión creada en un mal momento -- el contacto todavía no existía, o
// el flujo se rompió a medias -- se queda huérfana para siempre aunque el
// contacto aparezca después. Entry no lo sufre porque hace PATCH en cada turno;
// aquí solo hay una pasada por llamada, así que hay que decirlo.
const enlazar = Boolean(session_id && b.contact_id && !(sesion && sesion.contact_id));

return [{ json: {
  ...b,
  session_id,
  crear: posible && !session_id,
  enlazar,
  save: { session_key: b.session_key, canal: b.canal, contact_id: b.contact_id },
}}];

// El transcript viene SIEMPRE en el payload de Retell, así que una llamada puede
// leerse en la bandeja igual que un WhatsApp en vez de quedarse en un resumen.
// No es un concepto nuevo: es `conversation_messages` con `canal: voz`.
const n = $('Code · Normalizar').first().json;
const dec = $('Code · Sesión: decidir').first().json;
const c = $('Code · Clasificar y normalizar').first().json.llamada || {};
const yaHabia = (() => { const r = $json || {}; const f = (r.body && r.body.data) || []; return f.length > 0; })();

// Si la sesión se acaba de crear, el id está en la respuesta de ESE nodo.
let session_id = dec.session_id;
if (!session_id) {
  try {
    const r = $('HTTP · Crear sesión').first().json;
    session_id = (r.body && r.body.data && r.body.data.id) || null;
  } catch (e) { session_id = null; }
}

const turnos = Array.isArray(c.transcript_object) ? c.transcript_object : [];
const filas = [];
if (session_id && !yaHabia) {
  turnos.forEach((t, i) => {
    const texto = String((t && t.content) || '').trim();
    if (!texto) return;
    const delCliente = String(t.role || '') === 'user';
    filas.push({
      session_id, contact_id: dec.contact_id, canal: 'voz',
      direccion: delCliente ? 'entrante' : 'saliente',
      // 'lucia' y no 'humano': lo dijo el agente. 'humano' sigue reservado para
      // lo que escribe una persona del negocio en un relevo.
      autor: delCliente ? 'cliente' : 'lucia',
      texto,
      estado_envio: delCliente ? 'recibido' : 'enviado',
      // Lleva el índice para que un reintento se reconozca por prefijo y para no
      // perder el orden si dos filas comparten milisegundo.
      canal_message_id: `${n.call_id}#${String(i).padStart(3, '0')}`,
    });
  });
}

// UNA FILA POR ITEM, no un array en un item: así el nodo HTTP las inserta en
// orden y `created_at` va creciendo. Con un solo POST del array entero todas
// caerían en el mismo instante y el hilo se leería desordenado, que es
// exactamente lo que no queremos de una conversación.
if (!filas.length) {
  return [{ json: { _sin_turnos: true, motivo: !session_id ? 'sin sesión'
    : (yaHabia ? 'ya estaban escritos' : 'el transcript venía vacío') } }];
}
return filas.map((fila) => ({ json: { directus_base_url: dec.directus_base_url, ...fila } }));
